import{_ as e,o as a,c as r,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Macro-Loops.md","filePath":"manual-zh/Macro-Loops.md","lastUpdated":1785684581000}'),t={name:"manual-zh/Macro-Loops.md"};function p(n,o,d,l,c,i){return a(),r("div",null,[...o[0]||(o[0]=[s(`<h4 id="_14-2-9-macro-loops" tabindex="-1">14.2.9 Macro Loops <a class="header-anchor" href="#_14-2-9-macro-loops" aria-label="Permalink to &quot;14.2.9 Macro Loops&quot;">​</a></h4><p>宏的主体可以包含两种形式的循环：遍历数值范围的循环和遍历记号的循环。两种形式都会多次展开_循环体_（loop body），每次将一个命名的_循环变量_（loop variable）设置为不同的值。循环体通常至少展开该循环变量一次。</p><p>MITERATE 设置（参见 <a href="./SET#SET-MITERATE">SET MITERATE</a>）限制循环中的迭代次数。这是一种确保宏展开终止的安全措施。当超过 MITERATE 限制时，PSPP 会发出警告。</p><h4 id="loops-over-ranges" tabindex="-1">Loops Over Ranges <a class="header-anchor" href="#loops-over-ranges" aria-label="Permalink to &quot;Loops Over Ranges&quot;">​</a></h4><pre><code>!DO !var = start !TO end [!BY step]
  body
!DOEND
</code></pre><p>遍历数值范围的循环采用如上所示的形式。start、end 和 step（如果包含）必须是具有数值的表达式。宏处理器接受整数和实数。宏处理器对从 start 到 end（含）的每个数值展开 body。</p><p>step 的默认值为 1。如果 step 为正且 <em>first &gt; last</em>，或者 step 为负且 <em>first &lt; last</em>，则宏处理器根本不展开 body。step 不能为零。</p><h4 id="loops-over-tokens" tabindex="-1">Loops Over Tokens <a class="header-anchor" href="#loops-over-tokens" aria-label="Permalink to &quot;Loops Over Tokens&quot;">​</a></h4><pre><code>!DO !var !IN (expression)
  body
!DOEND
</code></pre><p>遍历记号的循环采用如上所示的形式。宏处理器求值 expression，并对结果中的每个记号展开 body 一次，每次出现时将记号替换 <code>!var</code>。</p>`,10)])])}const m=e(t,[["render",p]]);export{h as __pageData,m as default};
